import {levels,percentages,demoProvider} from './model.js';
const app=document.querySelector('#app'),nav=document.querySelector('#navigation');
const colors=['#08735b','#946407','#bd4c20','#b5253c'],tints=['#e7f4ed','#fff4d9','#fff0e7','#fcebef'],fills=['#81bca1','#ebcd7b','#e89968','#cd6477'];
const state={step:0,profile:'household',map:false,selected:'VE-A',updated:new Date()};
let geography,zoom=1,pan={x:0,y:0};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function theme(step){document.documentElement.style.setProperty('--accent',colors[step]);document.documentElement.style.setProperty('--tint',tints[step]);}
const demo='<span class="demo">DEMO DATA</span>';
function dashboard(){theme(state.step);const p=demoProvider.prediction(state.step,state.profile),medical=state.profile==='medical';app.innerHTML=`<div class="intro"><div><p class="eyebrow">Your current location</p><h1 tabindex="-1">Caracas, Venezuela</h1></div>${demo}</div><div class="layout"><div class="column"><section class="card hero" aria-label="Power outage risk"><div class="hero-top"><div><h2>Power Outage Risk</h2><p class="muted">Next 30 minutes</p></div><span class="risk-badge">${p.level.toUpperCase()}</span></div><div class="probability" aria-label="${p.percentage} percent">${p.percentage}<span>%</span></div><div class="prob-label">Predicted probability of an outage · demo</div><div class="spectrum">${levels.map((l,i)=>`<span class="${i===state.step?'active':''}">${l}</span>`).join('')}</div><p class="status" role="status">${p.status}</p><div class="timestamp"><span>Updated ${state.updated.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span><span>Simulated prediction</span></div></section><section class="card"><h2>Live Grid Conditions</h2><p class="muted" style="margin:6px 0 0">Simulated signals for this demo</p><div class="grid-rows">${[['Grid stability',p.stability],['Electricity demand',p.demand],['Weather risk',p.level]].map(([a,b])=>`<div class="grid-row"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div></section></div><div class="column"><section class="card"><p class="eyebrow">Preparedness for you</p><div class="profile-switch" aria-label="Preparedness profile"><button data-profile="household" aria-pressed="${!medical}">Household</button><button data-profile="medical" aria-pressed="${medical}">Medical Power Dependency</button></div><div class="section-rule"></div><h2>${medical?'Medical Power Readiness':'Recommended Actions'}</h2><p class="muted" style="margin:8px 0">${medical?'Keep essential care powered.':'Small steps. Better prepared.'}</p>${medical?`<div class="readiness"><p>EXAMPLE DEVICE</p><div class="battery"><span>Oxygen Concentrator</span><strong>42 <small>min</small></strong></div><p>Backup battery · demo estimate · remaining</p></div>${state.step>=2?`<div class="warning"><strong>${state.step===3?'Prepare backup power immediately':'Prioritise medical backup power'}</strong><p>Confirm your backup plan and contact your support person if needed.</p></div>`:''}`:''}<ul class="actions">${p.actions.map(a=>`<li><span class="check" aria-hidden="true">✓</span><span>${a}</span></li>`).join('')}</ul>${medical?'<p class="disclaimer">Preparedness guidance only. Follow your equipment instructions and personal care plan. This is not a medical diagnosis tool.</p>':''}</section><section class="simulation"><div class="sim-heading"><p class="eyebrow">Demo simulation</p><button class="reset" id="reset">Reset ↺</button></div><button class="primary" id="simulate" ${state.step===3?'disabled':''}><span>${state.step===3?'Critical reached · Reset to replay':'Simulate Grid Deterioration'}</span><span aria-hidden="true">→</span></button><div class="sim-bottom"><span>Explore how guidance changes with risk</span><div class="steps" aria-label="Step ${state.step+1} of 4">${levels.map((_,i)=>`<i class="${i<=state.step?'on':''}"></i>`).join('')}</div></div></section></div></div>`;
app.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{state.profile=b.dataset.profile;dashboard();app.querySelector(`[data-profile="${state.profile}"]`).focus();});
app.querySelector('#simulate').onclick=()=>{state.step=Math.min(3,state.step+1);state.updated=new Date();dashboard();app.querySelector(state.step===3?'#reset':'#simulate').focus();};app.querySelector('#reset').onclick=()=>{state.step=0;state.updated=new Date();dashboard();app.querySelector('#reset').focus();};}
const point=([x,y])=>[(x+73.8)/14.5*800,(13-y)/12.8*710];
function polygonPath(geometry){const polys=geometry.type==='Polygon'?[geometry.coordinates]:geometry.coordinates;return polys.map(poly=>poly.map(ring=>ring.map((p,i)=>`${i?'L':'M'}${point(p).map(n=>n.toFixed(2)).join(',')}`).join('')+'Z').join('')).join('');}
async function mapPage(){theme(0);app.innerHTML=`<div class="intro"><div><p class="eyebrow">A wider view</p><h1 tabindex="-1">Venezuela</h1></div>${demo}</div><div class="map-layout"><section class="card map-card"><div class="map-heading"><div><h2>Regional outage risk</h2><p class="muted" style="margin:6px 0">Next 30 minutes · Demo predictions</p></div><span class="eyebrow" style="white-space:nowrap;margin-top:5px">25 regions</span></div><div class="legend">${levels.map((l,i)=>`<span style="--c:${fills[i]}">${l}</span>`).join('')}</div><div class="map-wrap" aria-label="Interactive Venezuela administrative regions"><div class="muted" style="padding:30px" role="status">Loading regional boundaries…</div></div><p class="source">Boundaries: OCHA Venezuela / INE via <a href="https://www.geoboundaries.org/api/current/gbOpen/VEN/ADM1/" target="_blank" rel="noopener">geoBoundaries ↗</a> · 2020 · <a href="https://creativecommons.org/licenses/by/3.0/igo/" target="_blank" rel="noopener">CC BY 3.0 IGO</a>. <a href="assets/BOUNDARY-LICENSE.txt">Attribution</a></p></section><aside class="card region-panel" aria-label="Selected region"></aside></div>`;
try{if(!geography){const r=await fetch('assets/venezuela-adm1.geojson');if(!r.ok)throw Error('Boundary file unavailable');geography=await r.json();}if(!state.map)return;
const wrap=app.querySelector('.map-wrap');wrap.innerHTML=`<svg viewBox="0 0 800 710" role="group" aria-label="Map of Venezuela. Select a region, or use the region list."><g id="map-transform">${geography.features.map(f=>{const s=demoProvider.regionStep(f.properties.shapeISO,state.step);return `<path class="region" data-region="${escape(f.properties.shapeISO)}" role="button" tabindex="0" aria-label="${escape(f.properties.shapeName)}, ${s===null?'no data':levels[s]+' risk'}" fill="${s===null?'#ccc':fills[s]}" fill-rule="evenodd" d="${polygonPath(f.geometry)}"><title>${escape(f.properties.shapeName)}</title></path>`;}).join('')}<text x="365" y="45" class="sea" text-anchor="middle">CARIBBEAN SEA</text>${[['ZULIA',-72.1,10.2],['APURE',-69,7],['BOLÍVAR',-63.8,6.1],['AMAZONAS',-66,3.1]].map(([n,x,y])=>{const p=point([x,y]);return `<text x="${p[0]}" y="${p[1]}" class="map-label" text-anchor="middle">${n}</text>`;}).join('')}<circle cx="380" cy="140" r="5" fill="#173e35" stroke="white" stroke-width="2" pointer-events="none"/><text x="392" y="135" class="map-label">Caracas</text></g></svg><div class="map-controls"><button id="zoom-in" aria-label="Zoom in">+</button><button id="zoom-out" aria-label="Zoom out">−</button><button id="fit" aria-label="Fit map">Fit map</button></div>`;
wrap.querySelectorAll('[data-region]').forEach(el=>{el.onclick=()=>selectRegion(el.dataset.region);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRegion(el.dataset.region);}};});
const transform=()=>{wrap.querySelector('#map-transform').setAttribute('transform',`translate(${400*(1-zoom)+pan.x} ${355*(1-zoom)+pan.y}) scale(${zoom})`);wrap.querySelector('#zoom-in').disabled=zoom>=4;wrap.querySelector('#zoom-out').disabled=zoom<=1;};
wrap.querySelector('#zoom-in').onclick=()=>{zoom=Math.min(4,zoom+.5);transform();};wrap.querySelector('#zoom-out').onclick=()=>{zoom=Math.max(1,zoom-.5);if(zoom===1)pan={x:0,y:0};transform();};wrap.querySelector('#fit').onclick=()=>{zoom=1;pan={x:0,y:0};transform();};
const svg=wrap.querySelector('svg');let last=null,moved=false;svg.addEventListener('pointerdown',e=>{if(zoom<=1)return;last={x:e.clientX,y:e.clientY};moved=false;});svg.addEventListener('pointermove',e=>{if(!last)return;const ratio=800/svg.getBoundingClientRect().width;const dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;pan.x=Math.max(-1000,Math.min(1000,pan.x+dx*ratio));pan.y=Math.max(-1000,Math.min(1000,pan.y+dy*ratio));last={x:e.clientX,y:e.clientY};transform();});svg.addEventListener('click',e=>{if(moved){e.stopPropagation();moved=false;}},true);window.onpointerup=()=>last=null;svg.onpointerleave=()=>last=null;svg.onpointercancel=()=>last=null;transform();selectRegion(state.selected);
}catch(e){if(state.map)app.querySelector('.map-wrap').innerHTML='<div class="error">The map could not load. <button id="retry">Try again</button></div>';app.querySelector('#retry')?.addEventListener('click',mapPage);}}
function selectRegion(code){state.selected=code;app.querySelectorAll('[data-region]').forEach(el=>{el.classList.toggle('selected',el.dataset.region===code);el.setAttribute('aria-pressed',String(el.dataset.region===code));});const f=geography.features.find(f=>f.properties.shapeISO===code);const step=demoProvider.regionStep(code,state.step);const panel=app.querySelector('.region-panel');panel.style.setProperty('--accent',colors[step]||'#65776c');panel.style.setProperty('--tint',tints[step]||'#eee');panel.innerHTML=`<div><label class="eyebrow" for="region-select">Explore ADM1 regions</label><select id="region-select">${[...geography.features].sort((a,b)=>a.properties.shapeName.localeCompare(b.properties.shapeName)).map(f=>`<option value="${escape(f.properties.shapeISO)}" ${f.properties.shapeISO===code?'selected':''}>${escape(f.properties.shapeName)}</option>`).join('')}</select><div aria-live="polite"><p class="eyebrow">${escape(code)}</p><h2>${escape(f.properties.shapeName)}</h2><p class="muted">${code==='VE-A'?'Caracas · current demo location':'Regional demo prediction'}</p></div></div><div><div class="probability">${step===null?'—':percentages[step]}<span>%</span></div><div class="prob-label">Outage probability · next 30 minutes</div><span class="risk-badge">${step===null?'NO DATA':levels[step].toUpperCase()}</span><p class="map-note">Select a region on the map or from the list. Use + to zoom, then drag to explore.</p><p class="disclaimer">Regional predictions are fictional demo values. They do not represent current electricity conditions.</p></div>`;panel.querySelector('select').onchange=e=>{selectRegion(e.target.value);panel.querySelector('select').focus();};}
function navigate(map){state.map=map;nav.innerHTML=map?'Current location <span aria-hidden="true">↙</span>':'Map <span aria-hidden="true">↗</span>';if(map)mapPage();else dashboard();app.querySelector('h1')?.focus({preventScroll:true});window.scrollTo(0,0);}
nav.onclick=()=>navigate(!state.map);document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate(false);};dashboard();
